create table public.roles (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, slug text not null, name text not null, description text not null, ability text not null, sort_order smallint not null default 0, unique(story_id,slug));
create table public.secret_missions (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, role_id uuid references public.roles(id), title text not null, description text not null, success_condition jsonb not null default '{}', score integer not null default 0);
create table public.session_player_roles (session_id uuid not null references public.game_sessions(id) on delete cascade, player_id uuid not null references public.players(id) on delete cascade, role_id uuid not null references public.roles(id), active boolean not null default true, assigned_at timestamptz not null default now(), delegated_from_player_id uuid references public.players(id), delegated_at timestamptz, primary key(session_id,player_id));
create table public.session_secret_missions (player_id uuid primary key references public.players(id) on delete cascade, secret_mission_id uuid not null references public.secret_missions(id), status text not null default 'active', progress jsonb not null default '{}', completed_at timestamptz);
create table public.acts (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, number smallint not null, slug text not null, title text not null, summary text not null, sort_order smallint not null, unique(story_id,slug));
create table public.story_steps (id uuid primary key default gen_random_uuid(), act_id uuid not null references public.acts(id) on delete cascade, slug text not null, type text not null, title text not null, content jsonb not null default '{}', responsible_role_slug text, conditions jsonb not null default '[]', effects jsonb not null default '[]', next_step_rules jsonb not null default '{}', envelope_id uuid, timer_config jsonb, score_config jsonb, sort_order smallint not null, unique(act_id,slug));
create table public.decisions (id uuid primary key default gen_random_uuid(), story_step_id uuid not null references public.story_steps(id) on delete cascade, options jsonb not null, voting_mode text not null default 'majority', tie_break_role text, duration_seconds integer);
create table public.session_decisions (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.game_sessions(id) on delete cascade, decision_id uuid not null references public.decisions(id), selected_option text, decided_by_player_id uuid references public.players(id), created_at timestamptz not null default now());
create table public.votes (id uuid primary key default gen_random_uuid(), session_decision_id uuid not null references public.session_decisions(id) on delete cascade, player_id uuid not null references public.players(id), option_id text not null, sealed boolean not null default false, created_at timestamptz not null default now(), unique(session_decision_id,player_id));
create table public.puzzles (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, step_id uuid references public.story_steps(id), slug text not null, answer_hash text not null, normalization_rule text not null default 'trim_upper', max_attempts smallint not null default 3, metadata jsonb not null default '{}');
create table public.puzzle_attempts (id bigint generated always as identity primary key, puzzle_id uuid not null references public.puzzles(id), session_id uuid not null references public.game_sessions(id) on delete cascade, player_id uuid references public.players(id), is_correct boolean not null, created_at timestamptz not null default now());
create table public.hints (id uuid primary key default gen_random_uuid(), puzzle_id uuid not null references public.puzzles(id) on delete cascade, level smallint not null, content text not null, penalty integer not null default 0, cooldown integer not null default 0);
create table public.session_hints (id bigint generated always as identity primary key, session_id uuid not null references public.game_sessions(id) on delete cascade, hint_id uuid not null references public.hints(id), requested_by uuid references public.players(id), created_at timestamptz not null default now());
create table public.envelopes (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, code text not null, title text not null, instructions text not null, physical_manifest jsonb not null default '{}', unique(story_id,code));
create table public.session_envelopes (session_id uuid not null references public.game_sessions(id) on delete cascade, envelope_id uuid not null references public.envelopes(id), status text not null default 'sealed', unlocked_at timestamptz, opened_at timestamptz, opened_by_player_id uuid references public.players(id), primary key(session_id,envelope_id));
create table public.inventory_items (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, code text not null, name text not null, description text not null, scope text not null default 'collective', max_uses smallint, effects jsonb not null default '{}', physical_reference text);
create table public.session_inventory (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.game_sessions(id) on delete cascade, inventory_item_id uuid not null references public.inventory_items(id), owner_player_id uuid references public.players(id), status text not null default 'available', remaining_uses smallint, acquired_at timestamptz not null default now(), used_at timestamptz);
create table public.messages (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, character_slug text, type text not null, content text not null, options jsonb not null default '{}', visibility text not null default 'collective', conditions jsonb not null default '{}');
create table public.session_messages (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.game_sessions(id) on delete cascade, message_id uuid not null references public.messages(id), recipient_player_id uuid references public.players(id), status text not null default 'unread', response text, created_at timestamptz not null default now(), read_at timestamptz);
create table public.media_assets (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, code text not null, kind text not null, storage_path text, caption_path text, transcript text, duration_seconds integer, status text not null default 'placeholder');
create table public.score_events (id bigint generated always as identity primary key, session_id uuid not null references public.game_sessions(id) on delete cascade, player_id uuid references public.players(id), category text not null, points integer not null, reason text not null, created_at timestamptz not null default now());
create table public.restoration_items (id uuid primary key default gen_random_uuid(), story_id uuid not null references public.stories(id) on delete cascade, code text not null, label text not null, envelope_code text not null, quantity integer not null default 1, sort_order smallint not null default 0);
create table public.session_restoration_items (session_id uuid not null references public.game_sessions(id) on delete cascade, restoration_item_id uuid not null references public.restoration_items(id), checked boolean not null default false, checked_at timestamptz, primary key(session_id,restoration_item_id));
create table public.admin_audit_logs (id bigint generated always as identity primary key, admin_user_id uuid not null references auth.users(id), action text not null, entity_type text not null, entity_id uuid, payload jsonb not null default '{}', created_at timestamptz not null default now());

do $$ declare t text; begin foreach t in array array['roles','secret_missions','session_player_roles','session_secret_missions','acts','story_steps','decisions','session_decisions','votes','puzzles','puzzle_attempts','hints','session_hints','envelopes','session_envelopes','inventory_items','session_inventory','messages','session_messages','media_assets','score_events','restoration_items','session_restoration_items','admin_audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create or replace function public.is_session_member(target_session uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.game_sessions s where s.id=target_session and s.host_user_id=auth.uid()) or exists(select 1 from public.players p where p.session_id=target_session and p.auth_user_id=auth.uid()); $$;
create policy "members read story session roles" on public.session_player_roles for select using (public.is_session_member(session_id));
create policy "members read current events" on public.game_events for insert with check (public.is_session_member(session_id));
create policy "members read session messages" on public.session_messages for select using (public.is_session_member(session_id) and (recipient_player_id is null or exists(select 1 from public.players p where p.id=recipient_player_id and p.auth_user_id=auth.uid())));
create policy "members read session inventory" on public.session_inventory for select using (public.is_session_member(session_id));
create policy "members read envelopes" on public.session_envelopes for select using (public.is_session_member(session_id));
create policy "published media metadata" on public.media_assets for select using (exists(select 1 from public.stories s where s.id=story_id and s.status='published'));
